class ParallelDilatedConvBlock(nn.Module):
    """Parallel k=3 branches at multiple dilations, fused by a 1×1 conv.

    ``padding=d`` keeps each branch length-aligned so concat is per-base.
    Receptive field of a branch is ``1 + 2d`` (dilation 1/3/9 → 3/7/19 bp).
    """

    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        *,
        branch_channels: int | None = None,
        dilations: Tuple[int, ...] = DEFAULT_DILATIONS,
        kernel_size: int = 3,
    ):
        super().__init__()
        if kernel_size != 3:
            raise ValueError(f"ParallelDilatedConvBlock expects kernel_size=3, got {kernel_size}")
        if not dilations:
            raise ValueError("dilations must be non-empty")
        self.dilations = tuple(int(d) for d in dilations)
        self.kernel_size = int(kernel_size)
        c_branch = int(branch_channels) if branch_channels else int(out_channels)
        self.branch_channels = c_branch
        self.branches = nn.ModuleList(
            [
                nn.Conv1d(in_channels, c_branch, kernel_size, dilation=d, padding=d)
                for d in self.dilations
            ]
        )
        self.fuse = nn.Conv1d(c_branch * len(self.dilations), out_channels, kernel_size=1)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        ys = [F.relu(branch(x)) for branch in self.branches]
        return F.relu(self.fuse(torch.cat(ys, dim=1)))

    @property
    def receptive_field(self) -> int:
        return 1 + (self.kernel_size - 1) * max(self.dilations)

