def load_prokaryotic_model_v4_from_checkpoint(
    path: str,
    *,
    pool_size: int = 3,
    cnn_stride: Optional[int] = None,
    numb_conv: int = 4,
    numb_lstm: int = 1,
    output_size: int = NUM_CLASSES_V4,
    inp_size: int | None = None,
    device: Optional[torch.device] = None,
    head_mode: Optional[HeadMode] = None,
    enable_aux_head: bool = False,
    enable_dilated_stem: bool | None = None,
) -> ProkaryoticModelV4:
    """Build v4 with matching head layout and load weights."""
    try:
        ckpt = torch.load(path, map_location="cpu", weights_only=True)
    except TypeError:
        ckpt = torch.load(path, map_location="cpu")
    state = ckpt.get("model_state_dict", ckpt)
    stride = cnn_stride
    if stride is None:
        stride = int(ckpt.get("cnn_stride", infer_cnn_stride_from_state_dict(state, pool_size=pool_size)))
    arch = v4_arch_kwargs_from_checkpoint(
        ckpt,
        state,
        pool_size=pool_size,
        numb_conv=numb_conv,
        numb_lstm=numb_lstm,
        cnn_stride=stride,
        output_size=output_size,
        enable_dilated_stem=enable_dilated_stem,
    )
    ckpt_inp = int(state["initial_conv.weight"].shape[1]) if "initial_conv.weight" in state else 12
    target_inp = int(inp_size) if inp_size is not None else int(ckpt.get("inp_size", ckpt_inp))
    if target_inp != ckpt_inp:
        from .sd_channel import expand_v4_checkpoint_sd_channel

        filter_size = int(state["initial_conv.weight"].shape[0]) if "initial_conv.weight" in state else 64
        pool_size = int(arch.get("pool_size", pool_size))
        state = expand_v4_checkpoint_sd_channel(
            state,
            old_in=ckpt_inp,
            new_in=target_inp,
            filter_size=filter_size,
            pool_size=pool_size,
        )
    arch["inp_size"] = target_inp
    if head_mode is not None:
        arch["head_mode"] = head_mode
    arch["enable_aux_head"] = enable_aux_head or bool(ckpt.get("enable_aux_head", False))
    model = ProkaryoticModelV4(**arch)
    if device is not None:
        model = model.to(device)
    missing, unexpected = model.load_state_dict(state, strict=False)
    if missing:
        aux_missing = [k for k in missing if k.startswith("aux_dense")]
        dilated_missing = [k for k in missing if k.startswith("dilated_stem.")]
        other_missing = [
            k for k in missing
            if not k.startswith("aux_dense") and not k.startswith("dilated_stem.")
        ]
        if other_missing:
            raise RuntimeError(f"checkpoint missing required keys: {other_missing}")
        if aux_missing and not model.enable_aux_head:
            raise RuntimeError(f"checkpoint expects aux head but enable_aux_head=False: {aux_missing}")
        if dilated_missing and not model.enable_dilated_stem:
            raise RuntimeError(
                f"checkpoint missing dilated stem keys but enable_dilated_stem=False: {dilated_missing}"
            )
    if unexpected:
        print(f"warning: ignored unexpected checkpoint keys: {unexpected}")
    sd_flag, phase_flag = infer_input_flags_from_size(target_inp)
    model._sd_channel = bool(ckpt.get("enable_sd_channel", sd_flag))  # type: ignore[attr-defined]
    model._phase_channel = bool(ckpt.get("enable_phase_channel", phase_flag))  # type: ignore[attr-defined]
    return model


class V4BoundaryF1Loss(nn.Module):
    """Multi-label BCE on all 11 channels + soft F1 on merged START and STOP.

    START is max over +/− strand channels (7, 8); STOP over (9, 10), analogous to
    v3 ``BoundaryF1Loss`` on classes 4 and 5. Per-sequence F1 is averaged over batch
    sequences that contain at least one positive boundary (same masking as v3).
    """

    def __init__(self, f1_factor: float = 1.0):
        super().__init__()
        self.f1_factor = f1_factor
        self.bce = nn.BCEWithLogitsLoss()

    def _per_seq_f1_loss(self, pred: torch.Tensor, true: torch.Tensor) -> torch.Tensor:
        eps = 1e-6
        tp = (pred * true).sum(dim=1)
        pred_pos = pred.sum(dim=1)
        true_pos = true.sum(dim=1)
        precision = tp / (pred_pos + eps)
        recall = tp / (true_pos + eps)
        f1 = 2 * precision * recall / (precision + recall + eps)
        any_pos = (true_pos > 0).to(pred.dtype)
        denom = any_pos.sum().clamp_min(1.0)
        return 1.0 - (f1 * any_pos).sum() / denom

    def forward(self, logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        bce = self.bce(logits, target)
        probs = torch.sigmoid(logits)
        sp, sm = V4_CH_START_PLUS, V4_CH_START_MINUS
        zp, zm = V4_CH_STOP_PLUS, V4_CH_STOP_MINUS
        start_pred = torch.maximum(probs[:, :, sp], probs[:, :, sm])
        start_true = torch.maximum(target[:, :, sp], target[:, :, sm])
        stop_pred = torch.maximum(probs[:, :, zp], probs[:, :, zm])
        stop_true = torch.maximum(target[:, :, zp], target[:, :, zm])
        start_f1_loss = self._per_seq_f1_loss(start_pred, start_true)
        stop_f1_loss = self._per_seq_f1_loss(stop_pred, stop_true)
        return bce + self.f1_factor * 0.5 * (start_f1_loss + stop_f1_loss)


class V4TiberiusCCEF1Loss(nn.Module):
    """Tiberius-style CCE-F1 for v4 multi-label outputs.

    For v4 we use BCEWithLogitsLoss as the CCE analog, then add boundary F1
    terms over merged START/STOP channels. If a sequence has no positives for a
    boundary, we use a differentiable false-positive proxy (mean predicted
    probability) instead of ``1 - F1``.
    """

    def __init__(self, f1_factor: float = 2.0):
        super().__init__()
        self.f1_factor = float(f1_factor)
        self.bce = nn.BCEWithLogitsLoss()

    def _per_seq_term(self, pred: torch.Tensor, true: torch.Tensor) -> torch.Tensor:
        eps = 1e-6
        tp = (pred * true).sum(dim=1)
        pred_pos = pred.sum(dim=1)
        true_pos = true.sum(dim=1)
        precision = tp / (pred_pos + eps)
        recall = tp / (true_pos + eps)
        f1 = 2 * precision * recall / (precision + recall + eps)
        has_pos = true_pos > 0
        # dFPR proxy when a sequence has no positives: discourage false spikes.
        dfpr = pred.mean(dim=1)
        term = torch.where(has_pos, 1.0 - f1, dfpr)
        return term.mean()

    def forward(self, logits: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        bce = self.bce(logits, target)
        probs = torch.sigmoid(logits)
        sp, sm = V4_CH_START_PLUS, V4_CH_START_MINUS
        zp, zm = V4_CH_STOP_PLUS, V4_CH_STOP_MINUS
        start_pred = torch.maximum(probs[:, :, sp], probs[:, :, sm])
        start_true = torch.maximum(target[:, :, sp], target[:, :, sm])
        stop_pred = torch.maximum(probs[:, :, zp], probs[:, :, zm])
        stop_true = torch.maximum(target[:, :, zp], target[:, :, zm])
        start_term = self._per_seq_term(start_pred, start_true)
        stop_term = self._per_seq_term(stop_pred, stop_true)
        return bce + self.f1_factor * 0.5 * (start_term + stop_term)
